    64→        self.status = HealthStatus::Healthy
    65→        self.last_heartbeat = 1000
    66→        self.consecutive_failures = 0
    67→        self.cpu_usage = cpu
    68→        self.memory_usage = mem
    69→        return true
    70→    }
    71→
    72→    fn record_failure(&mut self) -> bool {
    73→        self.consecutive_failures += 1
    74→        if self.consecutive_failures > 3 {
    75→            self.status = HealthStatus::Dead
    76→        } else if self.consecutive_failures > 1 {
    77→            self.status = HealthStatus::Unhealthy
    78→        }
    79→        return true
    80→    }
    81→
    82→    fn is_healthy(&self) -> bool {
    83→        return match self.status {
    84→            HealthStatus::Healthy => true,
    85→            _ => false,
    86→        }
    87→    }
    88→
    89→    fn is_alive(&self) -> bool {
    90→        return match self.status {
    91→            HealthStatus::Dead => false,
    92→            _ => true,
    93→        }
    94→    }
    95→}
